public class LeetCode105 {

    public static void main(String[] args) {
        LeetCode105 leetCode105 = new LeetCode105();
        int[] preorder = {3, 9, 20, 15, 7};
        int[] inorder = {9, 3, 15, 20, 7};
        leetCode105.buildTree(preorder, inorder);
    }

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        if (preorder == null || inorder == null) {
            return null;
        }
        return buildTree(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1);
    }

    private TreeNode buildTree(int[] preorder, int preLeft, int preRight, int[] inorder, int inLeft, int inRight) {
        if (preLeft &gt; preRight || inLeft &gt; inRight) {
            return null;
        }
        int rootValue = preorder[preLeft];
        TreeNode root = new TreeNode(rootValue);
        int index = 0;
        for (int i = inLeft; i &lt;= inRight; i++) {
            if (inorder[i] == rootValue) {
                index = i;
                break;
            }
        }
        int leftLength = index - inLeft;
        root.left = buildTree(preorder, preLeft + 1, preLeft + leftLength, inorder, inLeft, index - 1);
        root.right = buildTree(preorder, preLeft + leftLength + 1, preRight, inorder, index + 1, inRight);
        return root;
    }

    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int x) {
            val = x;
        }
    }
